$passed=0;$total=0
function Case([string]$name,[scriptblock]$body){$script:total++;try{& $body;$script:passed++}catch{throw "$name : $($_.Exception.Message) [$($_.ScriptStackTrace)]"}}
function NewSynthetic {
    $store=Join-Path $tmp ([guid]::NewGuid().ToString('N'));$b=New-MayaQaBootstrap -StoreRoot $store -QaWorkflowId 'create-plan-views-v1' -RunId 'synthetic'
    $candidate=Join-Path $root 'DeploymentCandidates\AgentBuilds\ReleaseCandidate-fcf624ee3ed1';$dll=Join-Path $candidate 'Repato.Revit.dll';$hash=(Get-FileHash $dll -Algorithm SHA256).Hash;$commit='fcf624ee3ed1c84fcc2bb78e4bf46d92090b98f3'
    Invoke-RepatoStoreMutation $store {param($d,$preview)$x=Find-RepatoTask $d $b.TaskId;$w=@($x.deploymentWorkflows|Where-Object workflowId -ceq $b.WorkflowId)[0];$w|Add-Member NoteProperty qaBuildStatus 'succeeded' -Force;$w|Add-Member NoteProperty qaBuildRequest ([pscustomobject]@{BuildRequestId='build-synthetic'}) -Force;$w|Add-Member NoteProperty qaBuildEvidence ([pscustomobject]@{BuildRequestId='build-synthetic';EvidenceSource='FrozenCandidate';SourceCommit=$commit;CandidateSourceCommit=$commit;CandidateDirectory=$candidate;CandidateProvenancePath=(Join-Path $candidate 'release-manifest.json');ArtifactPath=$dll;ArtifactSha256=$hash;DeploymentValidation=$false}) -Force;$x|Add-Member NoteProperty approvalRequests @([pscustomobject]@{requestId='synthetic-approval';action='qa-run';status='pending'}) -Force;$d}|Out-Null
    [pscustomobject]@{Store=$store;TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;Candidate=$candidate;Hash=$hash;Commit=$commit}
}
