    $validation={param($e)$script:validationCount++;[pscustomobject]@{succeeded=$true;candidateSha256=$e.CandidateDllSha256;qaWorkflowId='create-plan-views-v1';testId='create-plan-views-v1';isolationPassed=$true;taskId=$c.TaskId;workflowId=$c.WorkflowId;runnerManifestPath=$runner;runnerManifestSha256=$rh;qaAddinRoot='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\RepatoQA'}}
    $revit={@()};$persist={param($v,$e)$script:persistCount++;Invoke-MayaQaFrozenCandidateEvidence -StoreRoot $c.Store -TaskId $c.TaskId -WorkflowId $c.WorkflowId -QaWorkflowId create-plan-views-v1 -CandidateDirectory $e.CandidateDirectory -CandidateDllPath $e.CandidateDllPath -ExpectedSha256 $c.Hash -ExpectedSourceCommit $c.Commit -DeploymentEvidence $v}
