t++;[pscustomobject]@{succeeded=$true;candidateSha256=$e.CandidateDllSha256;qaWorkflowId='bad';testId='create-plan-views-v1';isolationPassed=$true}}} 'validationhash' {$validation={param($e)$script:validationCount++;[pscustomobject]@{succeeded=$true;candidateSha256='B'*64;qaWorkflowId='create-plan-views-v1';testId='create-plan-views-v1';isolationPassed=$true}}} 'validationrunner' {$validation={param($e)$script:validationCount++;[pscustomobject]@{succeeded=$true;candidateSha256=$e.CandidateDllSha256;qaWorkflowId='create-plan-views-v1';testId='create-plan-views-v1';isolationPassed=$true;runnerManifestPath='bad';runnerManifestSha256=$rh}}} 'persist' {$persist={param($v,$e)$script:persistCount++;throw 'synthetic persistence failure'}}
