    try{$r=Invoke-MayaQaCanonicalFrozenCandidateStagingValidation @args;if($mode -ne 'success'){throw 'accepted invalid input'};if($stageCount -ne 1 -or $validationCount -ne 1 -or $persistCount -ne 1){throw 'success call counts invalid'};return $r}catch{if($mode -eq 'success'){throw};return $null}
