        $v={param($e)[pscustomobject]@{succeeded=$true;candidateSha256=$e.CandidateDllSha256;qaWorkflowId='create-plan-views-v1';testId='create-plan-views-v1';isolationPassed=$true;taskId=$c.TaskId;workflowId=$c.WorkflowId;runnerManifestPath=$runner;runnerManifestSha256=$rh;qaAddinRoot='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\RepatoQA'}}
        $r=Invoke-MayaQaCanonicalFrozenCandidateStagingValidation -StoreRoot $c.Store -TaskId $c.TaskId -WorkflowId $c.WorkflowId -QaWorkflowId create-plan-views-v1 -TestId create-plan-views-v1 -ExpectedBuildRequestId build-synthetic -ExpectedCandidateSourceCommit $c.Commit -ExpectedCandidateSha256 $c.Hash -ExpectedRunnerManifestPath $runner -ExpectedRunnerManifestSha256 $rh -HealthInvoker $h -PreflightInvoker $p -StagingInvoker $s -DeploymentValidationInvoker $v -RevitProcessProvider { @() }
